INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, 0.2, 1, "drama_talk_surprise_loop_shy", 6014, 129811, "drama_talk_surprise_in_shy", 3, 0, "", "");
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, "", "", 0, 6015, "vo_minigame_1013", "vo_minigame_1013_top_talk_6_002", 21, 0, "", "");
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, 0, 0, 1, 6016, 129811, "いやいや何でもない！\nあたしは別に変なこと\n考えてないからな！\nそれより訓練だっ！", 11, 9, 0, 0.3);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, "", "", "", 6017, 0, "", 91, "", "", "");
