INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (7, 0, 0, 1, 7006, 129911, "私の班のみなさんも\n変わらず訓練に励んで\nいるようですわね\n殊勝なことです", 11, 6, 0, 0.3);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (7, "", "", "", 7007, 0, "", 91, "", "", "");
