INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (8, "", "", 0, 8015, "vo_minigame_1013", "vo_minigame_1013_top_talk_8_002", 21, 0, "", "");
